export class LiveClassCreditManager { }

async function handleAdminBadges(request: Request, env: Env): Promise<Response> {
  try {
    await requireAdmin(request, env);
    const url = new URL(request.url);

    if (request.method === "GET") {
      const badges = await env.DB.prepare(`SELECT * FROM Badges ORDER BY created_at DESC`).all();
      return new Response(JSON.stringify(badges.results || []), { status: 200, headers: { "Content-Type": "application/json" } });
    }

    if (request.method === "POST") {
      const body: any = await request.json();
      const id = generateCustomId("YA-BDG");
      await env.DB.prepare(`
        INSERT INTO Badges (id, name, description, icon, xp_reward, criteria_type, criteria_value)
        VALUES (?, ?, ?, ?, ?, ?, ?)
      `).bind(id, body.name, body.description, body.icon, body.xp_reward, body.criteria_type, body.criteria_value).run();
      return new Response(JSON.stringify({ success: true, id }), { status: 201, headers: { "Content-Type": "application/json" } });
    }

    if (request.method === "PUT") {
      const body: any = await request.json();
      const match = url.pathname.match(/^\/api\/admin\/badges\/([^/]+)$/);
      const id = match ? match[1] : null;
      if (!id) return new Response("Missing ID", { status: 400 });

      await env.DB.prepare(`
        UPDATE Badges SET name = ?, description = ?, icon = ?, xp_reward = ?, criteria_type = ?, criteria_value = ? WHERE id = ?
      `).bind(body.name, body.description, body.icon, body.xp_reward, body.criteria_type, body.criteria_value, id).run();
      return new Response(JSON.stringify({ success: true }), { status: 200, headers: { "Content-Type": "application/json" } });
    }

    if (request.method === "DELETE") {
      const match = url.pathname.match(/^\/api\/admin\/badges\/([^/]+)$/);
      const id = match ? match[1] : null;
      if (!id) return new Response("Missing ID", { status: 400 });

      await env.DB.prepare(`DELETE FROM Badges WHERE id = ?`).bind(id).run();
      return new Response(JSON.stringify({ success: true }), { status: 200, headers: { "Content-Type": "application/json" } });
    }

    return new Response("Method not allowed", { status: 405 });
  } catch (e) {
    return handleGlobalError(e, "Admin.Badges", env, request);
  }
}

async function handleUserGamification(request: Request, env: Env): Promise<Response> {
  try {
    const token = getCookie(request, "session");
    if (!token) return new Response("Unauthorized", { status: 401 });
    const jwtSecret = await getCachedJwtSecret(env);
    if (!jwtSecret) throw new Error("JWT_SECRET missing");
    const payload = await verifyJWT(token, jwtSecret, env.ENVIRONMENT);
    const userId = payload.sub;

    const completedLessons = await env.DB.prepare(`SELECT count(*) as total FROM CompletedLessons WHERE user_id = ?`).bind(userId).first();
    const lessonCount = (completedLessons?.total as number) || 0;

    const completedCoursesRes = await env.DB.prepare(`SELECT count(*) as total FROM Enrollments WHERE user_id = ? AND status = 'completed'`).bind(userId).first();
    const courseCount = (completedCoursesRes?.total as number) || 0;

    // Fetch earned badges
    const userBadges = await env.DB.prepare(`
      SELECT b.*, ub.earned_at 
      FROM UserBadges ub
      JOIN Badges b ON ub.badge_id = b.id
      WHERE ub.user_id = ?
    `).bind(userId).all();

    // Base XP from lessons/courses, plus XP from every badge the user has already earned.
    let earnedXp = (lessonCount * 50) + (courseCount * 500);
    const earnedBadgeIds = new Set();
    userBadges.results.forEach((b: any) => {
      earnedBadgeIds.add(b.id);
      earnedXp += (b.xp_reward || 0);
    });

    // Check all badges to see if the user qualifies for any new ones
    const allBadges = await env.DB.prepare(`SELECT * FROM Badges`).all();
    const newBadgesEarned = [];

    for (const badge of allBadges.results as any[]) {
      if (!earnedBadgeIds.has(badge.id)) {
        let qualifies = false;
        if (badge.criteria_type === 'lessons_completed' && lessonCount >= badge.criteria_value) qualifies = true;
        if (badge.criteria_type === 'course_completed' && courseCount >= badge.criteria_value) qualifies = true;

        if (qualifies) {
          const ubId = generateCustomId("YA-UBG");
          await env.DB.prepare(`INSERT INTO UserBadges (id, user_id, badge_id) VALUES (?, ?, ?)`).bind(ubId, userId, badge.id).run();
          newBadgesEarned.push(badge);
          earnedXp += (badge.xp_reward || 0);
        }
      }
    }

    // Level calculation (e.g. Level 1 = 0 XP, Level 2 = 1000 XP, etc.)
    const currentLevel = Math.floor(earnedXp / 1000) + 1;
    const nextLevelXp = currentLevel * 1000;

    return new Response(JSON.stringify({
      xp: earnedXp,
      level: currentLevel,
      nextLevelXp,
      earnedBadges: [...userBadges.results, ...newBadgesEarned],
      allBadges: allBadges.results
    }), { status: 200, headers: { "Content-Type": "application/json" } });

  } catch (e) {
    return handleGlobalError(e, "User.Gamification", env, request);
  }
}

async function handleExamViolation(request: Request, env: Env, examId: string): Promise<Response> {
  try {
    const token = getCookie(request, "session");
    if (!token) return new Response("Unauthorized", { status: 401 });
    const jwtSecret = await getCachedJwtSecret(env);
    if (!jwtSecret) throw new Error("JWT_SECRET missing");
    const payload = await verifyJWT(token, jwtSecret, env.ENVIRONMENT);
    const userId = payload.sub;

    const body = await request.json() as { type: string; message: string; timestamp: string };

    // Store violation in D1 as an error session
    const violationId = generateCustomId("YA-VIO");
    await env.DB.prepare(`
      INSERT INTO ErrorSessions (id, fingerprint, source, severity, title, error_message, full_payload, stack_trace, user_id, url)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      violationId,
      `proctoring-${examId}-${userId}-${body.type}`,
      "frontend",
      "medium",
      `Proctoring Violation: ${body.type}`,
      body.message || "No message",
      JSON.stringify(body),
      body.message || "No message",
      userId,
      `/api/exams/${examId}`
    ).run();

    return new Response(JSON.stringify({ success: true }), { status: 200, headers: { "Content-Type": "application/json" } });
  } catch (e) {
    return handleGlobalError(e, "Exam.Violation", env, request);
  }
}


async function handlePlayIntegrity(request: Request, env: Env): Promise<Response> {
  try {
    const { token } = (await request.json()) as any;
    if (!token) return new Response(JSON.stringify({ error: "Token required" }), { status: 400 });

    const clientIp = request.headers.get("cf-connecting-ip") || "unknown";

    // Play Integrity API check using Google APIs
    // Get Service Account Credentials from KV or Secret
    const googleServiceAccountStr = await getSecret(env, "PLAY_INTEGRITY_SERVICE_ACCOUNT_JSON");
    if (!googleServiceAccountStr) {
      console.warn("PLAY_INTEGRITY_SERVICE_ACCOUNT_JSON not configured Ã¢ÂÂ session-based auth will be used");
      return new Response(JSON.stringify({ token: null }), { status: 200, headers: { "Content-Type": "application/json" } });
    }

    try {
        const credentials = JSON.parse(googleServiceAccountStr);
        // Step 1: Get OAuth2 Access Token
        const jwtHeader = { alg: "RS256", typ: "JWT" };
        const now = Math.floor(Date.now() / 1000);
        const jwtPayload = {
          iss: credentials.client_email,
          scope: "https://www.googleapis.com/auth/playintegrity",
          aud: credentials.token_uri,
          exp: now + 3600,
          iat: now,
        };

        const encoder = new TextEncoder();
        const base64url = (str: string) => btoa(str).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

        const signingInput = base64url(JSON.stringify(jwtHeader)) + "." + base64url(JSON.stringify(jwtPayload));

        const pemHeader = "-----BEGIN PRIVATE KEY-----";
        const pemFooter = "-----END PRIVATE KEY-----";
        const pemContents = credentials.private_key.substring(
          pemHeader.length,
          credentials.private_key.length - pemFooter.length - 1
        ).replace(/\s/g, "");
        const binaryDer = Uint8Array.from(atob(pemContents), (c) => c.charCodeAt(0));

        const cryptoKey = await crypto.subtle.importKey(
          "pkcs8",
          binaryDer,
          { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
          false,
          ["sign"]
        );

        const signature = await crypto.subtle.sign(
          "RSASSA-PKCS1-v1_5",
          cryptoKey,
          encoder.encode(signingInput)
        );

        const sigB64 = base64url(String.fromCharCode(...new Uint8Array(signature)));
        const googleJwt = `${signingInput}.${sigB64}`;

        const authReq = await fetchWithTimeout(credentials.token_uri, {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer",
            assertion: googleJwt,
          }),
        }, 5000);

        const authRes: any = await authReq.json();
        const accessToken = authRes.access_token;

        if(!accessToken) throw new Error("Failed to get Google Access Token");

        // Step 2: Call Play Integrity API
        const packageName = "com.yagyaashram.lms";
        const url = `https://playintegrity.googleapis.com/v1/${packageName}:decodeIntegrityToken`;

        const playReq = await fetchWithTimeout(url, {
           method: "POST",
           headers: {
             "Authorization": `Bearer ${accessToken}`,
             "Content-Type": "application/json"
           },
           body: JSON.stringify({ integrityToken: token })
        }, 5000);

        const playRes: any = await playReq.json();

        // Step 3: Validate the response
        // If Play Integrity fails (e.g. debug build, unrecognized app version),
        // don't block Ã¢ÂÂ fall back to session-based auth gracefully.
        // Proper Play Integrity verification is enforced only for production
        // builds published on Google Play Store.
        if (playRes.error || !playRes.tokenPayloadExternal || playRes.tokenPayloadExternal.appIntegrity.appRecognitionVerdict !== 'PLAY_RECOGNIZED') {
             console.warn("Play Integrity Check Failed (non-blocking)", playRes);
             return new Response(JSON.stringify({ token: null }), { status: 200, headers: { "Content-Type": "application/json" } });
        }

        // Integrity Passed
        const appSecret = await getSecret(env, "APP_API_SECRET");
        if(!appSecret) throw new Error("APP_API_SECRET missing");

        // Generate secure token valid for 24 hours
        const newToken = await signJWT({ sub: 'play_integrity_verified', env: env.ENVIRONMENT, exp: Math.floor(Date.now() / 1000) + 24 * 60 * 60 }, appSecret);
        return new Response(JSON.stringify({ token: newToken }), { headers: { "Content-Type": "application/json" }});

    } catch (gErr) {
        console.warn("Google API error (non-blocking)", gErr);
        return new Response(JSON.stringify({ token: null }), { status: 200, headers: { "Content-Type": "application/json" } });
    }

  } catch (error) {
    return handleGlobalError(error, "Auth.PlayIntegrity", env, request);
  }
}
export default worker;

